#ifndef FINDMY_BEACON_H
#define FINDMY_BEACON_H

#include <stdbool.h>
#include <stdint.h>

// Apple "offline finding" (Find My) beacon, same advertisement format as the
// OpenHaystack reference firmware: a legacy 31-byte non-connectable ADV whose
// public key is a P-224 point generated by the host companion app.
#define FINDMY_BEACON_KEY_LEN 28
#define FINDMY_BEACON_RECORD_VERSION 1

typedef struct {
    uint8_t version;
    uint8_t enable;                                  // user enabled the beacon
    uint8_t reserved[2];                             // FDS records are rounded up to 32-bit words
    uint8_t key[FINDMY_BEACON_KEY_LEN];              // P-224 public key, host generated
} findmy_beacon_config_t;

// Load the key/enable state from flash and start advertising when enabled.
// Must be called after fds_util_init() and ble_slave_init(); typically from
// check_wakeup_src() in app_main.c.
void findmy_beacon_init(void);

// Set the whole configuration (key + enable flag) and persist it. Starts or
// stops the BLE advertising set immediately. Returns false on flash error.
bool findmy_beacon_set_config(const findmy_beacon_config_t *cfg);

// Toggle the beacon and persist the flag. Returns false on flash error.
bool findmy_beacon_set_enable(bool enable);

// Enable/disable the short RGB blink that findmy_beacon_set_config() emits.
// The button handler uses it so the toggle state is visible without the app;
// it is off by default (protocol callers get no LED animation).
void findmy_beacon_set_led_feedback(bool enable);

// Read the current configuration (a copy, never NULL).
void findmy_beacon_get_config(findmy_beacon_config_t *cfg);

// True when the user enabled the beacon and the key is valid.
bool findmy_beacon_is_enabled(void);

// True when at least one key byte is non-zero (a key was provisioned).
bool findmy_beacon_has_key(void);

// True when the beacon advertising set is actually running on air.
bool findmy_beacon_is_active(void);

// Called from the BLE disconnect handler: re-apply the beacon address once no
// link is up (the SoftDevice forbids changing the address while connected).
void findmy_beacon_on_ble_disconnected(void);

// (Re)start the beacon advertising set if the user enabled it. Used by the
// BLE disconnect path, where the connectable advertisement used to restart.
void findmy_beacon_start_if_enabled(void);

// Keep-awake guard used by utils/syssleep.c: the beacon must survive deep
// sleep decisions just like an active NFC field or BLE connection.
bool findmy_beacon_should_stay_awake(void);

#endif
